// X, Y 좌표와 실제 위경도, 지명 정보를 담는 구조체
struct LocationData {
    int16_t gridX;
    int16_t gridY;
    double lat;
    double lon;
    const char* name;
};

// 지명으로 X, Y를 찾기 위한 구조체
struct LocationName {
    const char* name;
    int16_t gridX;
    int16_t gridY;
};

